SELECT sales_line_hk, order_hk, product_hk, customer_hk, employee_hk, order_key, order_line_number, order_date, order_date_key, order_status, currency_code, quantity, unit_price, discount_amount, gross_amount, net_amount, discount_rate, lead_time_days, is_cancelled, ship_date, delivery_date, ship_date_key, delivery_date_key FROM {gold}.historical.fct_sales_hist WHERE is_current AND NOT coalesce(is_cancelled, false)
